mapper.update:
UPDATE ${updateSurface} SET is_used = #{ipUse},

    update_user = #{userId},

update_time = now()
WHERE subnet = #{deviceSubnet}
AND ip IN

    #{item}

update ${ipPoolName} t
set t.is_used = '1'
where t.is_used <> '2'
  and t.subnet = #{subnet}
  and t.ip = #{ip}

mapper.select:
SELECT
ip.*,
sb.subnet_name AS subnetName,
dept.dept_name AS orgName
FROM
${param.ipPoolName} ip
LEFT JOIN idevelop_safeaccess_subnet sb ON ip.subnet = sb.id and sb.is_deleted = 0
LEFT JOIN idevelop_dept dept ON ip.org_no = dept.id and dept.is_deleted = 0
WHERE
1=1
and ip.ip =#{param.ip}
and ip.ip_level =#{param.level}
and ip.is_used =#{param.isUsed}
and ip.subnet =#{param.subnet}
and ip.org_no=#{param.orgNo}
order by ip.order_no*1 asc

SELECT t.ip_id, t.org_no, t.subnet, t.ip, t.ip_level, t.is_used, t.BAK_COL1 bakCol1, t.BAK_COL2 bakCol2, t.BAK_COL3 bakCol3, a.dept_name AS orgName, c.subnet_name AS subnetName, ctua.is802, ctua.mac_address as mac, ctua.device_type_name as deviceType, (case when sh3cou.framed_ip_str is null then '离线' else '在线' end) as online FROM ${ipPoolName} t left join idevelop_safeaccess_subnet c on t.subnet = c.id and c.is_deleted = 0 left join idevelop_dept a on t.org_no = a.id and a.is_deleted = 0 left join sdn_h3c_online_user sh3cou on sh3cou.framed_ip_str = t.ip left join idevelop_safeaccess_user_access ctua on ctua.ip_address = t.ip and ctua.is_deleted = 0 and t.subnet = ctua.subnet_id
t.is_deleted = 0
and t.ip like CONCAT('%',#{ip},'%')
and t.ip like CONCAT('%',#{ippoolSegment},'%')
and t.ip_level =#{ipLevel}
and t.is_used =#{isUsed}
and t.subnet =#{subnet}
and t.org_no=#{orgNo}
order by t.order_no*1 asc

SELECT ip.*, sb.subnet_name AS subnetName, dept.dept_name AS orgName FROM ${ipPoolName} ip LEFT JOIN idevelop_safeaccess_subnet sb ON ip.subnet = sb.id and sb.is_deleted = 0 LEFT JOIN idevelop_dept dept ON ip.org_no = dept.id and dept.is_deleted = 0 WHERE 1=1 and ip.ip like CONCAT('%',#{ip},'%') and ip.ip_level =#{level} and ip.is_used =#{isUsed} and ip.subnet =#{subnet} and ip.org_no=#{orgNo}
AND ip.ip NOT IN
#{excludeIp}
order by ip.order_no*1 asc

SELECT count(1) FROM ${updateSurface}
WHERE is_used = 1 AND ip IN

    #{item}

SELECT *
FROM ${ipPoolName}
WHERE is_deleted = 0
  AND subnet = #{subnet}
  AND ip = #{ip}

SELECT iss.network_type AS networkType, isi.is_used AS isUsed, count(*) AS number FROM ${ipPoolDB} isi LEFT JOIN idevelop_safeaccess_subnet iss ON iss.id = isi.subnet
isi.is_used IN (0, 1)
AND iss.network_type IN
#{item}
AND iss.region_code = #{regionCode}
GROUP BY iss.network_type,isi.is_used
